const priority = "HIGH";
const done = false;

if (priority === "HIGH" && !done) {
  console.log("Work on this task first");
} else {
  console.log("Continue normally");
}

function createTask(title, priority = "MEDIUM") {
  const trimmed = title.trim();
  if (!trimmed) throw new Error("Title is required");
  return { id: crypto.randomUUID(), title: trimmed, priority, done: false };
}

const task = createTask("  Learn scope  ");
console.log(task.title);

const tasks = [
  { id: 1, title: "JS", done: true },
  { id: 2, title: "React", done: false },
  { id: 3, title: "Next", done: false },
];

const openTitles = tasks
  .filter(task => !task.done)
  .map(task => task.title);

console.log(openTitles);

const original = { id: 1, title: "Learn JS", done: false };
const alias = original;
alias.done = true;

console.log(original.done);

function findTask(tasks, id) {
  const task = tasks.find(task => task.id === id);
  if (!task) throw new Error(`Task ${id} not found`);
  return task;
}

try {
  findTask([], "missing");
} catch (error) {
  console.error(error.message);
}

